{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C40"],
      "claim": "Emtricitabine, a polar cytidine analog with an oxathiolane sugar, has an absolute oral bioavailability of 93% in HIV-infected subjects, demonstrating that highly polar nucleoside analogs can achieve F well above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C62"],
      "claim": "Lamivudine, another polar cytidine analog, has an absolute oral bioavailability of 86–88% in adults across oral solution, capsule, and tablet formulations, supporting high F for ribose-like nucleosides.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Zidovudine, a dideoxynucleoside with an azido group, has an oral bioavailability of 60% in humans, further showing that nucleoside analogs with polar and ionizable groups can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Rufinamide, a carboxamide-bearing azole, has an absolute oral bioavailability of 85% in humans, supporting that the carboxamide-azole motif does not preclude high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C68"],
      "claim": "Didanosine can have an oral bioavailability as low as 14% in children when given as a solution with antacid, showing that some nucleoside analogs can fall below 20%; however, this is formulation- and acid-lability-dependent and not representative of the query's full ribose scaffold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a polar ribonucleoside with a carboxamide-substituted azole. Although physicochemical priors predict poor permeability, multiple high-transfer experimental measurements in nucleoside analogs (emtricitabine 93%, lamivudine 86–88%, zidovudine 60%) and a carboxamide-azole drug (rufinamide 85%) show that such polar nucleosides can achieve F ≥ 20%, often via transporter-mediated absorption. The only sub-20% evidence (didanosine 14%) is tied to acid lability and formulation, not the query's full ribose scaffold. Therefore predict high.",
  "evidence_gaps": [
    "No direct oral bioavailability data for the exact query molecule.",
    "No experimental data on the query's nucleoside transporter affinity, metabolism, or efflux.",
    "Didanosine's low F illustrates condition-dependent variability, but its acid lability limits direct transferability to the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

